// DeepCopyInto for AgentSpec. Ref slices copy by value (no pointer state
// to preserve); Env + Resources use the same shape as Skill/Model.
func (in *AgentSpec) DeepCopyInto(out *AgentSpec) {
	*out = *in
	out.Service = in.Service
	in.Resources.DeepCopyInto(&out.Resources)
	if in.ModelRefs != nil {
		out.ModelRefs = make([]LocalObjectReference, len(in.ModelRefs))
		copy(out.ModelRefs, in.ModelRefs)
	}
	if in.SkillRefs != nil {
		out.SkillRefs = make([]LocalObjectReference, len(in.SkillRefs))
		copy(out.SkillRefs, in.SkillRefs)
	}
	if in.Env != nil {
		out.Env = make([]v1core.EnvVar, len(in.Env))
		for i := range in.Env {
			in.Env[i].DeepCopyInto(&out.Env[i])
		}
	}
	if in.DLPRef != nil {
		ref := *in.DLPRef
		out.DLPRef = &ref
	}
	if in.Egress != nil {
		out.Egress = in.Egress.DeepCopy()
	}
}

